with inserted as (insert into public.platform_updates(slug,title,summary,body,next_step,status,category,created_at,updated_at,published) values('updates-samen-verder','Een vaste plek om MyGrowise te zien groeien','Volg verbeteringen van het eerste idee tot de oplevering, en denk mee op de plek waar het gebeurt.','Je krijgt een eigen Updates-sectie in je werkruimte. Per onderwerp lees je wat er verandert, waarom dat helpt en welke stappen al gezet zijn.

Je kunt een vraag of opmerking achterlaten. Het antwoord blijft bij hetzelfde onderwerp staan, zodat je het later rustig terugvindt.','De schermen, opslag en feedback worden lokaal gecontroleerd. Daarna volgen de uitrol en de controle op de live website.','in_progress','Werkruimte','2026-11-18T12:00:00+02:00','2026-11-18T12:00:00+02:00',true) on conflict(slug) do nothing returning *) insert into public.platform_update_events(update_id,title,body,status,revision,created_at) select id,'Het idee krijgt vorm','Het plan is besproken: verbeteringen lezen, van begin tot eind opvolgen en feedback geven. Dat is de basis van deze nieuwe plek.',status,1,created_at from inserted;
with inserted as (insert into public.platform_updates(slug,title,summary,body,next_step,status,category,created_at,updated_at,published) values('mail-verzonden-terugvinden','Terugvinden welke mails zijn verstuurd','De mailopvolging maakt onderscheid tussen verzonden, geplande en onbevestigde berichten.','Je kunt in de mailopvolging teruglezen welke berichten als verzonden zijn geregistreerd. Geplande berichten en verzendingen die aandacht vragen, krijgen een eigen plek.

Bij oudere berichten is niet altijd bekend hoe een verzending is afgelopen. Die worden apart aangeduid, zodat de lijst helder blijft. Een geregistreerde verzending is geen bevestiging dat iemand de mail heeft gelezen.','De verzendgeschiedenis is op 18 november gecontroleerd.','released','Werkruimte','2026-11-18T12:00:00+02:00','2026-11-18T12:00:00+02:00',true) on conflict(slug) do nothing returning *) insert into public.platform_update_events(update_id,title,body,status,revision,created_at) select id,'De verzendgeschiedenis is gecontroleerd','De uitbreiding is uitgerold en de geregistreerde aantallen zijn met de geschiedenis vergeleken. Onzekere oudere verzendingen blijven apart herkenbaar.',status,1,created_at from inserted;
with inserted as (insert into public.platform_updates(slug,title,summary,body,next_step,status,category,created_at,updated_at,published) values('clientgegevens-afspraakkeuze','Cliëntgegevens en afspraken krijgen meer ruimte','Een duidelijker onderscheid tussen wie je cliënt is en hoe je een afspraak plant.','In november is gewerkt aan het bewaren van cliëntgegevens en een duidelijkere afspraakkeuze. Daardoor kunnen de gegevens van een cliënt en de planning elk een eigen plek krijgen.

Deze terugblik beschrijft het vastgelegde werk. Latere verbeteringen volgen als afzonderlijke stappen.','Nieuwe verbeteringen aan de cliëntwerkruimte worden apart opgevolgd.','historical','Agenda & cliënten','2026-11-17T12:00:00+02:00','2026-11-17T12:00:00+02:00',true) on conflict(slug) do nothing returning *) insert into public.platform_update_events(update_id,title,body,status,revision,created_at) select id,'Cliëntgegevens en afspraakkeuze uitgewerkt','De projectgeschiedenis legt het bewaren van gegevens en het apart kiezen van een therapeut bij afspraken vast.',status,1,created_at from inserted;
with inserted as (insert into public.platform_updates(slug,title,summary,body,next_step,status,category,created_at,updated_at,published) values('fien-interactief-lezen','Fien krijgt een interactieve leeswereld','Een digitaal boek waarin lezen en ontdekken samenkomen.','In november kreeg het digitale boek van Fien een interactieve leesomgeving. Er is gewerkt aan bladeren, tekenmogelijkheden en kleine ontdekkingen in de illustraties.

Ook de aankoop en toegang tot het boek zijn als eigen onderdelen uitgewerkt. Deze terugblik bundelt die bouwstappen tot één verhaal.','Verdere verbeteringen worden bij een nieuwe update toegelicht.','historical','Aanbod & aankopen','2026-11-09T12:00:00+02:00','2026-11-09T12:00:00+02:00',true) on conflict(slug) do nothing returning *) insert into public.platform_update_events(update_id,title,body,status,revision,created_at) select id,'De leeswereld is opgebouwd','De vastgelegde bouwstappen omvatten de boekweergave, illustraties, tekenmogelijkheden en toegang na aankoop.',status,1,created_at from inserted;
with inserted as (insert into public.platform_updates(slug,title,summary,body,next_step,status,category,created_at,updated_at,published) values('praktijk-afspraken-dossiers','Afspraken en dossiers dichter bij elkaar','De praktijkwerking kreeg een samenhangende flow voor afspraken en cliëntendossiers.','Eind oktober is de samenhang tussen het plannen van afspraken en het werken met dossiers uitgewerkt. De projectdocumentatie bevat controles van die praktijkflow.

Het doel van dit werk was dat de dagelijkse begeleiding een duidelijke plaats kreeg in MyGrowise.','Verbeteringen aan de huidige werkruimte worden apart beschreven.','historical','Agenda & cliënten','2026-10-30T12:00:00+02:00','2026-10-30T12:00:00+02:00',true) on conflict(slug) do nothing returning *) insert into public.platform_update_events(update_id,title,body,status,revision,created_at) select id,'De praktijkflow is doorlopen','Afspraken en dossiers zijn samen gecontroleerd als onderdeel van de praktijkwerking.',status,1,created_at from inserted;
with inserted as (insert into public.platform_updates(slug,title,summary,body,next_step,status,category,created_at,updated_at,published) values('website-rustiger-op-telefoon','Een website die ook op je telefoon prettig leest','De publieke pagina’s kregen aandacht voor leesbaarheid, navigatie en kleinere schermen.','In oktober is gewerkt aan de mobiele weergave van de website. Onder meer de homepage, navigatie en accountpagina’s zijn verfijnd voor kleinere schermen.

De veranderingen zijn gebundeld rond één doel: bezoekers makkelijker hun weg laten vinden.','Nieuwe aanpassingen krijgen hun eigen uitleg en opvolging.','historical','Website','2026-10-29T12:00:00+02:00','2026-10-29T12:00:00+02:00',true) on conflict(slug) do nothing returning *) insert into public.platform_update_events(update_id,title,body,status,revision,created_at) select id,'De mobiele pagina’s zijn verfijnd','De projectgeschiedenis beschrijft verbeteringen aan de pagina-indeling, het menu en de weergave op telefoon.',status,1,created_at from inserted;
with inserted as (insert into public.platform_updates(slug,title,summary,body,next_step,status,category,created_at,updated_at,published) values('startpunt-een-passende-route','Een persoonlijker startpunt voor bezoekers','Een korte keuzehulp helpt bezoekers een passende richting te verkennen.','De startpuntpagina kreeg een keuzehulp met drie oriënterende vragen. Bezoekers verkennen daarmee een richting naar een persoonlijk profiel of begeleiding.

De vragen helpen oriënteren; ze geven geen diagnose. De vormgeving combineert warme kleuren met fotografie uit de praktijk.','Deze terugblik beschrijft de ontwikkeling van de keuzehulp.','historical','Website','2026-10-29T12:00:00+02:00','2026-10-29T12:00:00+02:00',true) on conflict(slug) do nothing returning *) insert into public.platform_update_events(update_id,title,body,status,revision,created_at) select id,'De keuzehulp kreeg haar vorm','De startpuntflow en de visuele uitwerking zijn als samenhangend onderdeel vastgelegd.',status,1,created_at from inserted;
with inserted as (insert into public.platform_updates(slug,title,summary,body,next_step,status,category,created_at,updated_at,published) values('bestellen-toegang','Van bestellen naar toegang','Aankoop, betaling en toegang zijn als samenhangende stappen uitgewerkt.','Vanaf september is gewerkt aan de weg van een bestelling naar toegang tot het digitale aanbod. Daarbij zijn ook de uitleg rond overschrijvingen en de opvolging door de beheerder uitgewerkt.

Een handmatige betaling vraagt controle voordat toegang kan worden bevestigd. De uitleg voor klanten moet dat begrijpelijk maken.','Deze terugblik bundelt de eerste bouwstappen; latere veranderingen worden apart gevolgd.','historical','Aanbod & aankopen','2026-09-24T12:00:00+02:00','2026-09-24T12:00:00+02:00',true) on conflict(slug) do nothing returning *) insert into public.platform_update_events(update_id,title,body,status,revision,created_at) select id,'De aankoopflow is uitgewerkt','Bestellingen, betaalopvolging en toegang kregen een plek in de werking van MyGrowise.',status,1,created_at from inserted;
with inserted as (insert into public.platform_updates(slug,title,summary,body,next_step,status,category,created_at,updated_at,published) values('agenda-eerste-werkruimte','De agenda krijgt een centrale plek','Een eigen agenda legde de basis voor afspraken binnen de werkruimte.','In september kreeg de superadmin een centrale agenda. De eerste bouwstappen gingen over kalenderweergave en het plannen van afspraken.

Sindsdien is die werkruimte verder gegroeid. Deze terugblik markeert het begin van dat onderdeel.','Latere verbeteringen aan de agenda worden afzonderlijk beschreven.','historical','Agenda & cliënten','2026-09-21T12:00:00+02:00','2026-09-21T12:00:00+02:00',true) on conflict(slug) do nothing returning *) insert into public.platform_update_events(update_id,title,body,status,revision,created_at) select id,'De centrale agenda is opgebouwd','De kalender kreeg een eigen plek binnen het superadmin.',status,1,created_at from inserted;
with inserted as (insert into public.platform_updates(slug,title,summary,body,next_step,status,category,created_at,updated_at,published) values('eerste-basis-mygrowise','Hier begon MyGrowise','De eerste vastgelegde versie vormde het vertrekpunt voor de website en de werkruimte.','Op 18 september 2026 is de eerste versie van MyGrowise vastgelegd in de projectgeschiedenis. Van daaruit zijn de publieke website, het digitale aanbod en de praktijkwerking verder opgebouwd.

Deze plek bewaart de grote stappen van dat verhaal, in gewone taal.','Volg de recentere onderwerpen om te zien hoe MyGrowise verder groeit.','historical','Website','2026-09-18T12:00:00+02:00','2026-09-18T12:00:00+02:00',true) on conflict(slug) do nothing returning *) insert into public.platform_update_events(update_id,title,body,status,revision,created_at) select id,'Het vertrekpunt is vastgelegd','De eerste projectversie vormt het begin van de bewaarde geschiedenis.',status,1,created_at from inserted;
